local config = {
  ui_story_30460401_1_dialog_content = "Ever since the Keating Choir arrived, many people have been saying that there's something wrong with the way they talk.",
  ui_story_30460401_2_dialog_content = "I've told everyone that they should just tell the children what they think directly.",
  ui_story_30460401_3_dialog_content = "But everyone says that it's better to keep silent.",
  ui_story_30460401_4_dialog_content = "Dear adult, how's your mental state coming along?",
  ui_story_30460401_5_dialog_content = "Why do you look so distracted? Are you talking to yourself?",
  ui_story_30460401_6_dialog_content = "I'm sorry, I was thinking about something.",
  ui_story_30460401_7_dialog_content = "I was thinking about why you like to mock or make fun of other people all the time.",
  ui_story_30460401_8_dialog_content = "Ahem, everyone bears a little grudge even though they haven't said anything to you.",
  ui_story_30460401_9_dialog_content = "The troubled adults are losing their hair♪",
  ui_story_30460401_10_dialog_content = "I'm not losing my hair because of stress! Don't make things up!",
  ui_story_30460401_11_dialog_content = "Either way, you are always ignoring others and say strange things without any regard for others.",
  ui_story_30460401_12_dialog_content = "You shouldn't act like that. At the very least, <color=#FFB400>I hope that you can listen to what others are saying when you communicate with them</color>.",
  ui_story_30460401_13_dialog_content = "It's so tough to be you. You're always thinking about things. You don't see a way out when you look up, and you don't see the road on the ground when you look down.",
  ui_story_30460401_14_dialog_content = "That's why I keep saying that it's so tiring talking to you...",
  ui_story_30460401_15_option_content = "I don't even know which one of you is talking.",
  ui_story_30460401_16_dialog_content = "You should know our names.",
  ui_story_30460401_17_dialog_content = "But we factor in your response time.",
  ui_story_30460401_18_dialog_content = "That's why we say things line by line.",
  ui_story_30460401_19_dialog_content = "To give you a chance.",
  ui_story_30460401_20_dialog_content = "You'll be trying your best from now on, right? Do you still need us to take care of you?",
  ui_story_30460401_21_dialog_content = "I can sense the mockery in how you said \"Take care.\"",
  ui_story_30460401_22_option_content = "I don't understand.",
  ui_story_30460401_23_dialog_content = "What did you mean by \"you don't see the road on the ground when you look down\"?",
  ui_story_30460401_24_dialog_content = "Surely you know that it's easy to trip over if you don't watch where you're going.",
  ui_story_30460401_25_dialog_content = "Are you referring to how I almost tripped over when I walked over here? Fine...",
  ui_story_30460401_26_dialog_content = "Then what did you mean by \"You don't see a way out when you look up\"?",
  ui_story_30460401_27_dialog_content = "Well, have you come up with any good ideas yet?",
  ui_story_30460401_28_dialog_content = "What do you mean by that?",
  ui_story_30460401_29_dialog_content = "It means you must have had it tough.",
  ui_story_30460401_30_dialog_content = "As I expected, you do explain, but you actually have no intention of making it clear to others, right?",
  ui_story_30460401_31_dialog_content = "When adults ask a question, of course we need to answer it.",
  ui_story_30460401_32_dialog_content = "Surely you would understand what we're saying. You would, wouldn't you?",
  ui_story_30460401_33_dialog_content = "Forget it. Let's change the topic. What was that about bringing me a gift?",
  ui_story_30460401_34_dialog_content = "To be honest, you've sent me so many messages and they're all over the place. I can barely understand them.",
  ui_story_30460401_35_dialog_content = "How can you so quickly leave the unsolved question behind?",
  ui_story_30460401_36_dialog_content = "And turn to think about the more important gift?",
  ui_story_30460401_37_dialog_content = "But before we bring this gift to you...",
  ui_story_30460401_38_dialog_content = "<color=#FFB400>We want to ask you if you can communicate properly with people.</color>",
  ui_story_30460401_39_dialog_content = "Hmm? Hold on, are you sure you're not getting it the other way round?",
  ui_story_30460401_40_option_content = "I was clearly telling you before that...",
  ui_story_30460401_41_dialog_content = "I hope you can communicate properly with others.",
  ui_story_30460401_42_dialog_content = "We use the same language.",
  ui_story_30460401_43_dialog_content = "How can the adults possibly not understand what we're saying?",
  ui_story_30460401_44_dialog_content = "I think I...",
  ui_story_30460401_45_option_content = "Forget it, just pretend I didn't say anything.",
  ui_story_30460401_46_dialog_content = "I didn't expect you to get confused so quickly that you can't even express yourself properly.",
  ui_story_30460401_47_dialog_content = "You said something and then denied it.",
  ui_story_30460401_48_dialog_content = "I was just...",
  ui_story_30460401_49_dialog_content = "Do you think your words usually have any weight to them?",
  ui_story_30460401_50_dialog_content = "Why are you suddenly asking me questions instead? You've even interrupted me...",
  ui_story_30460401_51_dialog_content = "Have you forgotten your troubles?",
  ui_story_30460401_52_dialog_content = "(Although I've suggested everyone to just tell the children what they think directly.)",
  ui_story_30460401_X52_dialog_content = "(But everyone says that it's better to keep silent.)",
  ui_story_30460401_53_dialog_content = "Huh? Did I say that by mistake just then?",
  ui_story_30460401_54_dialog_content = "Yup, but we'll take care of you.",
  ui_story_30460401_55_dialog_content = "You said that some people aren't happy with us.",
  ui_story_30460401_56_dialog_content = "You proposed a solution to this.",
  ui_story_30460401_57_dialog_content = "But the other adults rejected it.",
  ui_story_30460401_58_dialog_content = "So, you decided to tell us about it on behalf of everyone.",
  ui_story_30460401_59_dialog_content = "Hold on, I didn't take it as everyone rejecting my proposal, nor does it have anything to do with the <color=#FFB400>weight of my words</color>.",
  ui_story_30460401_60_dialog_content = "Dear, please answer my question. Do you think your words usually have any <color=#FFB400>weight</color> to them?",
  ui_story_30460401_61_option_content = "Of course they do!",
  ui_story_30460401_62_dialog_content = "Everyone follows my advice in battle!",
  ui_story_30460401_63_dialog_content = "Does that have anything to do with the weight of your words? Isn't it just because everyone finds it convenient?",
  ui_story_30460401_64_dialog_content = "Will you get angry if we say that?",
  ui_story_30460401_65_option_content = "Of course I can answer that... they don't.",
  ui_story_30460401_66_dialog_content = "I mean, after all, not even you are willing to listen to me, and you always interrupt...",
  ui_story_30460401_67_dialog_content = "Is this how you usually talk? Do you usually get interrupted all the time like this?",
  ui_story_30460401_68_dialog_content = "Will you get angry if we say that?",
  ui_story_30460401_69_dialog_content = "I'm not that immature to allow you to anger me so easily. I'm also used to it by now anyway.",
  ui_story_30460401_70_dialog_content = "But you said it yourself.",
  ui_story_30460401_71_dialog_content = "Many people bear a grudge against us, right?",
  ui_story_30460401_72_dialog_content = "Do you know why nobody expresses their opinion to us directly like you?",
  ui_story_30460401_73_dialog_content = "It's for the same reason that we wear our Lumopolis uniform when we sing.",
  ui_story_30460401_74_dialog_content = "Holding the holy book and the candlestick.",
  ui_story_30460401_75_dialog_content = "Showing everyone our reputation as the Choir.",
  ui_story_30460401_76_dialog_content = "So that everyone will let us continue.",
  ui_story_30460401_77_dialog_content = "No one will have any objections.",
  ui_story_30460401_78_dialog_content = "It's because we have the power and status to let us say whatever we want.",
  ui_story_30460401_79_dialog_content = "That's why our snark is tolerated.",
  ui_story_30460401_80_dialog_content = "Fine, like what you said, everyone tolerates you because you're the Choir.",
  ui_story_30460401_81_dialog_content = "But I have no intention of brow-beating you into changing your ways.",
  ui_story_30460401_82_dialog_content = "I just want equal communication.",
  ui_story_30460401_83_dialog_content = "Because you always do too much talking and not enough listening.",
  ui_story_30460401_84_dialog_content = "You must balance speaking and listening to achieve fairness.",
  ui_story_30460401_85_dialog_content = "<color=#FFB400>Guess you're not one of those high mucky-mucks who think they know everything</color>.",
  ui_story_30460401_86_dialog_content = "In that case, please accept this gift from us.",
  ui_story_30460401_87_dialog_content = "Dear PlayerName.",
  ui_story_30460401_88_dialog_content = "May people always help you.",
  ui_story_30460401_89_dialog_content = "May people always bless you.",
  ui_story_30460401_90_dialog_content = "This is a blessing from Lumopolis.",
  ui_story_30460401_91_dialog_content = "It also represents the Academy's friendship, which we are presenting on its behalf.",
  ui_story_30460401_92_dialog_content = "So, the gift is this blessing? And it's even an ordinary one at that?!",
  ui_story_30460401_93_dialog_content = "What should I do? I don't know why you suddenly said that to me, but I do feel like it's so sweet of you.",
  ui_story_30460401_94_dialog_content = "To answer your question.",
  ui_story_30460401_95_dialog_content = "This gift may resolve some of your problems.",
  ui_story_30460401_96_dialog_content = "You can call it the weight of our words.",
  ui_story_30460401_97_dialog_content = "You've been <color=#FFB400>publicly recognized and blessed by the Lumopolis Choir.</color>",
  ui_story_30460401_98_dialog_content = "From now on, everyone will see the halo that accompanies this when they look at you.",
  ui_story_30460401_99_dialog_content = "Your words would be of more importance and you'd attain the fairness you want.",
  ui_story_30460401_100_dialog_content = "Since you've said this, does that mean you're willing to change how you speak? Are you willing to curb the sarcasm and be extra sweet instead?!",
  ui_story_30460401_101_dialog_content = "Do you think we would agree? Do you think we will change for you?",
  ui_story_30460401_102_dialog_content = "Do other people have to change just because you ask them to?",
  ui_story_30460401_X102_dialog_content = "Do you think that your idea of a better way really is better?",
  ui_story_30460401_103_dialog_content = "No, no, no! You're not listening to what I'm saying anymore! What happened to the recognition, blessing, and thoughtfulness you showed me just then?!",
  ui_story_30460401_104_dialog_content = "You're so simple♫ ♬",
  ui_story_30460401_105_dialog_content = "You're so naive♪",
  ui_story_30460101_1_dialog_content = "I currently have a difficult task of putting together a dossier on Keating.",
  ui_story_30460101_2_dialog_content = "There are 2 boys and girls, but I've asked around and no one knows who is who...",
  ui_story_30460101_3_dialog_content = "It's so tough to be you, always mumbling to yourself, all sneaky and weird.",
  ui_story_30460101_4_dialog_content = "Since when was I sneaky or weird?",
  ui_story_30460101_5_dialog_content = "When you came walking, your body was hunched and your head was down♪ When you were thinking, you kept nagging with your face in a frown♪",
  ui_story_30460101_6_dialog_content = "Fine, I guess I said everything without realizing it...",
  ui_story_30460101_7_dialog_content = "In that case, I'm just going to ask you directly...",
  ui_story_30460101_X7_dialog_content = "Which two of you are male, and which two of you are female?",
  ui_story_30460101_8_dialog_content = "Since you have asked us a question, we need to test you first.",
  ui_story_30460101_9_dialog_content = "Why do I feel like you are always testing my patience?",
  ui_story_30460101_10_dialog_content = "Ahem, what do you want to test me on? Shoot.",
  ui_story_30460101_11_dialog_content = "Do you know my name?",
  ui_story_30460101_12_option_content = "Pierre",
  ui_story_30460101_13_dialog_content = "I'm sorry, but you're wrong.",
  ui_story_30460101_14_dialog_content = "No, no, I can't possibly have gotten it wrong. I'm sure your name is Pierre.",
  ui_story_30460101_15_dialog_content = "Cluck.",
  ui_story_30460101_16_dialog_content = "Our hen thinks that your answer is correct.",
  ui_story_30460101_17_dialog_content = "The hen actually admits things that you refused to admit?",
  ui_story_30460101_18_dialog_content = "Also, the hen's gender is actually really clear.",
  ui_story_30460101_19_dialog_content = "Next question♪",
  ui_story_30460101_20_option_content = "Kara",
  ui_story_30460101_21_dialog_content = "I'm sorry, but you're wrong.",
  ui_story_30460101_22_dialog_content = "Although I don't really want to, I have no choice but to carry out our treasured punishments.",
  ui_story_30460101_23_dialog_content = "I mean, you don't even know my name...",
  ui_story_30460101_24_dialog_content = "Will you really do something like this? Am I going to be punished?!",
  ui_story_30460101_25_dialog_content = "No, we won't.",
  ui_story_30460101_X25_dialog_content = "We were just joking with you.",
  ui_story_30460101_26_dialog_content = "You believed that? Just like that?",
  ui_story_30460101_27_dialog_content = "No, actually I...",
  ui_story_30460101_28_dialog_content = "Next question♪",
  ui_story_30460101_29_dialog_content = "What do you think is the difference between boys and girls in a choir?",
  ui_story_30460101_30_option_content = "There isn't any, is there?",
  ui_story_30460101_31_dialog_content = "You don't think about things. You are amazing. You ended the conversation immediately. You just want us to leave♪",
  ui_story_30460101_32_dialog_content = "I'm sorry! It isn't over, so don't leave yet!",
  ui_story_30460101_33_dialog_content = "You haven't thought carefully about what to ask♪",
  ui_story_30460101_34_dialog_content = "In that case, we can only get Pierre to sing for you.",
  ui_story_30460101_35_dialog_content = "Oh♪ everything is over♪",
  ui_story_30460101_36_dialog_content = "Do you really want to end this by singing one line? Don't even think of leaving until I finish asking you questions!",
  ui_story_30460101_37_option_content = "There's a difference, isn't there?",
  ui_story_30460101_38_dialog_content = "For example, aren't girls usually more elegant?",
  ui_story_30460101_39_dialog_content = "Do you want us to be uncultured on purpose to show that we're different?",
  ui_story_30460101_40_dialog_content = "I never expected you to make such a request. Regrettably, we don't swear at all.",
  ui_story_30460101_41_dialog_content = "I meant that their actions are more elegant!",
  ui_story_30460101_42_dialog_content = "We can prove that there's no difference between us in this regard by dancing.",
  ui_story_30460101_43_dialog_content = "What kind of strange dance is this? Why do you look like you're just swaying left and right?",
  ui_story_30460101_44_dialog_content = "It has ceased to do with elegance anymore. In fact, it looks mortifying!",
  ui_story_30460101_45_dialog_content = "It looks like you're still not happy with our answer. What do we have to do to satisfy you?",
  ui_story_30460101_46_dialog_content = "Please don't put it like that. You're making it sound like I'm forcing you to do something...",
  ui_story_30460101_47_dialog_content = "I just want to know who is what gender...",
  ui_story_30460101_48_dialog_content = "We'll tell you the answer you want if you can answer our final question♪",
  ui_story_30460101_49_dialog_content = "Okay, ask me then. But you should make the question readily understandable!",
  ui_story_30460101_50_dialog_content = "Of course. Listen carefully then♪",
  ui_story_30460101_51_dialog_content = "<color=#FFFFFF><size=35>(Niel) I know that two of the other three are boys.</size></color>",
  ui_story_30460101_52_dialog_content = "<color=#FFFFFF><size=35>(Kara) I know that Pierre is a boy.</size></color>",
  ui_story_30460101_53_dialog_content = "<color=#FFFFFF><size=35>(Pierre) I know that Dian is a boy.</size></color>",
  ui_story_30460101_54_dialog_content = "<color=#FFFFFF><size=35>(Dian) I know that I am a girl.</size></color>",
  ui_story_30460101_55_dialog_content = "<color=#FFFFFF><size=35>(Pierre) I know that the boys are telling the truth, and the girls are lying.</size></color>",
  ui_story_30460101_56_dialog_content = "It could be as Pierre said, or it could be the complete opposite.",
  ui_story_30460101_57_dialog_content = "Now do you know which of us are boys and which of us are girls?",
  ui_story_30460101_58_dialog_content = "This... If I could answer this, I wouldn't need you to tell me the answer, okay?!",
  ui_story_30460101_59_dialog_content = "Are you finally going to stop? Are you finally going to give up?",
  ui_story_30460101_60_dialog_content = "Wait! I know that 2 of you are boys and 2 of you are girls...",
  ui_story_30460101_61_dialog_content = "According to what you just said, 2 of you must be telling the truth and the other 2 must be telling lies. Am I right?",
  ui_story_30460101_62_dialog_content = "Yes.",
  ui_story_30460101_63_dialog_content = "We'll help you out by asking a simpler question.",
  ui_story_30460101_X63_dialog_content = "Is Niel a boy or a girl?",
  ui_story_30460101_64_option_content = "Niel is a boy.",
  ui_story_30460101_65_dialog_content = "Did you just get lucky, or did you work out the answer?",
  ui_story_30460101_66_dialog_content = "Ahem, this isn't important. The important thing is, was I right?",
  ui_story_30460101_67_dialog_content = "You were right.",
  ui_story_30460101_68_dialog_content = "No, you were wrong.",
  ui_story_30460101_69_dialog_content = "Huh???",
  ui_story_30460101_70_option_content = "Niel is a girl.",
  ui_story_30460101_71_dialog_content = "Actually, Niel is a boy.",
  ui_story_30460101_72_dialog_content = "What?! But Niel has delicate features and looks so elegant!",
  ui_story_30460101_73_dialog_content = "Are you saying that we don't have delicate features?",
  ui_story_30460101_74_dialog_content = "How did you arrive at that conclusion?!",
  ui_story_30460101_75_dialog_content = "So, is Niel really a boy?",
  ui_story_30460101_76_dialog_content = "No, Niel is a girl.",
  ui_story_30460101_77_dialog_content = "Huh???",
  ui_story_30460101_78_dialog_content = "This won't do. You're confusing me again. Just announce the answer. We had an agreement.",
  ui_story_30460101_79_dialog_content = "Don't you remember what Pierre said?",
  ui_story_30460101_80_dialog_content = "I remember. I answered, and Pierre was supposed to tell me the answer if I answered!",
  ui_story_30460101_81_dialog_content = "We'll tell you the answer you want if you can answer our final question♪",
  ui_story_30460101_82_dialog_content = "Oh♪ are you thinking about getting something for nothing? That would be too idealistic and too easy♪",
  ui_story_30460101_83_dialog_content = "You didn't tell me if my answer was right or not, but I don't mind since you didn't say that my answer had to be correct.",
  ui_story_30460101_84_dialog_content = "Sorry, we never intended to tell you directly.",
  ui_story_30460101_85_dialog_content = "But...",
  ui_story_30460101_86_dialog_content = "Also, we want to tell you one more thing.",
  ui_story_30460101_87_dialog_content = "I know that boys told the truth and girls told lies.",
  ui_story_30460101_88_dialog_content = "It could be as Pierre said, or it could be the complete opposite.",
  ui_story_30460101_89_dialog_content = "This might not always be what happens, <color=#FFB400>but someone told an obvious lie as well.</color>",
  ui_story_30460101_90_dialog_content = "<color=#FFB400>But someone told you an obvious truth as well.</color>",
  ui_story_30460101_91_dialog_content = "Please think carefully.",
  ui_story_30460101_92_dialog_content = "Use your last hint.",
  ui_story_30460101_93_dialog_content = "If you still don't know <color=#FFB400>which of us are boys and which of us are girls.</color>",
  ui_story_30460101_94_dialog_content = "Think of something yourself. Dig deep into your memories until your hair starts falling out♪",
  ui_story_30460101_95_dialog_content = "I will, but I'm definitely not losing my hair just because I'm trying hard to remember! Don't make things up!",
  ui_story_30460201_1_dialog_content = "...",
  ui_story_30460201_2_dialog_content = "City Lord, you seem to be in a bad mood. Did something happen?",
  ui_story_30460201_3_dialog_content = "Our dear PlayerName is here♪",
  ui_story_30460201_4_dialog_content = "You're moving slowly and weighing your words; did you get scolded, or did you run away with your tail between your legs?",
  ui_story_30460201_5_dialog_content = "Ahem, I'm certainly delighted that you're greeting me.",
  ui_story_30460201_6_dialog_content = "But it's obvious that the City Lord is upset with all of you, so stop messing around.",
  ui_story_30460201_7_dialog_content = "Someone gave me a flower...",
  ui_story_30460201_8_dialog_content = "I-isn't that a good thing?",
  ui_story_30460201_9_dialog_content = "In the lounge, someone put a flower behind my ear when I was resting...",
  ui_story_30460201_10_option_content = "Could it be Keating?",
  ui_story_30460201_11_dialog_content = "Is that why you were glaring severely at Keating? Is it because of this?",
  ui_story_30460201_12_dialog_content = "Oh, dear PlayerName, your eyes only have the City Lord and not us♪",
  ui_story_30460201_13_dialog_content = "You're still singing?! Don't you care the City Lord might blow a fuse?",
  ui_story_30460201_14_dialog_content = "...",
  ui_story_30460201_15_dialog_content = "His demeanor didn't change, but who's to say he's not about to explode?",
  ui_story_30460201_16_option_content = "Who would dare?!",
  ui_story_30460201_17_dialog_content = "I mean, who would dare prank the City Lord?!",
  ui_story_30460201_18_dialog_content = "No one else dares other than these children.",
  ui_story_30460201_19_dialog_content = "City Lord, are you angry?",
  ui_story_30460201_20_dialog_content = "Dear PlayerName speaks so loudly when flattering others. Dear PlayerName is so obviously trying to get in someone's good books♪",
  ui_story_30460201_21_dialog_content = "...",
  ui_story_30460201_22_dialog_content = "You played a prank and then have the gall to ask if I was angry?",
  ui_story_30460201_23_dialog_content = "Angry? Since you're here, why don't you appease this anger?",
  ui_story_30460201_24_dialog_content = "Youngster, you are the master of the Colossus. This is your territory, so you should decide.",
  ui_story_30460201_25_dialog_content = "I know. In that case, can I make a record of this?",
  ui_story_30460201_26_dialog_content = "I just want to keep a record of all major incidents that have taken place on the Colossus.",
  ui_story_30460201_27_dialog_content = "A special record exclusive to the Colossus? Fine, I give you my permission.",
  ui_story_30460201_28_dialog_content = "<size=70>Colossus News</size>",
  ui_story_30460201_29_dialog_content = "The <color=#FFB400>Keating Flower Incident</color> took place on the Colossus today. Let's take a closer look.",
  ui_story_30460201_30_dialog_content = "This is based on the scene and the narration of Schwartz the City Lord.",
  ui_story_30460201_31_dialog_content = "We can tell that he clearly suspects the Keating quartet...",
  ui_story_30460201_32_dialog_content = "You... This is a rather special way of recording things.",
  ui_story_30460201_33_dialog_content = "Ahem, Vice and I came up with this...",
  ui_story_30460201_34_dialog_content = "We came up with this new recording method after referring to many sources of information, and we are currently testing it out.",
  ui_story_30460201_35_dialog_content = "All the incident records will be attached with detailed and lively explanations, making them precise and easy to read.",
  ui_story_30460201_36_dialog_content = "Dear PlayerName♪ you aren't letting Keating speak♪",
  ui_story_30460201_37_dialog_content = "Are you trying to exclude us? Do you only want to play with the City Lord?",
  ui_story_30460201_38_dialog_content = "Sorry, just let me make a descriptive record first.",
  ui_story_30460201_39_dialog_content = "Let's formally begin then. I'll get you to speak soon.",
  ui_story_30460201_40_dialog_content = "For this record, you'll need to <color=#FFB400>pay attention to the formality of your words and the display effect.</color>",
  ui_story_30460201_41_dialog_content = "That's enough for the explanation. Just get started...",
  ui_story_30460201_42_dialog_content = "In fact, the party suspected by the plaintiff seems to be dissatisfied with his conclusion.",
  ui_story_30460201_43_dialog_content = "Who? What?",
  ui_story_30460201_44_dialog_content = "Yes, you did it. You put this flower behind my ear when I was resting.",
  ui_story_30460201_45_dialog_content = "This is a misunderstanding.",
  ui_story_30460201_46_dialog_content = "You're angry because you mistook the flower for a prank.",
  ui_story_30460201_47_dialog_content = "But you shouldn't be angry.",
  ui_story_30460201_48_dialog_content = "Why?",
  ui_story_30460201_49_dialog_content = "Because an offering of flower represents respect.",
  ui_story_30460201_50_dialog_content = "That's what that <color=#FFB400>Uriah</color> taught us.",
  ui_story_30460201_51_dialog_content = "Sorry, I'll have to interrupt you here. Can I ask some questions?",
  ui_story_30460201_52_dialog_content = "I'll put everything down in the notes of the record.",
  ui_story_30460201_53_dialog_content = "PlayerName, you want to ask a question? Ask ahead♪",
  ui_story_30460201_54_option_content = "Ask about the flower.",
  ui_story_30460201_55_dialog_content = "How did you get your hands on this white flower in the Colossus?",
  ui_story_30460201_56_dialog_content = "You still don't know, you don't know what to ask♪",
  ui_story_30460201_57_dialog_content = "This is just a special white flower that the <color=#FFB400>big sister</color> grew with her Lumina. It bloomed because of the <color=#FFB400>big sister's</color> magic♪",
  ui_story_30460201_58_dialog_content = "Okay, I'll note that down.",
  ui_story_30460201_59_option_content = "Ask about the big sister.",
  ui_story_30460201_60_dialog_content = "She is our beloved <color=#FFB400>Uriah</color>, our beloved senior from the Academy♪",
  ui_story_30460201_61_dialog_content = "She taught us how to speak, and how to sing for the nobles♪",
  ui_story_30460201_62_dialog_content = "That's interesting information.",
  ui_story_30460201_63_dialog_content = "I see. I've noted that down.",
  ui_story_30460201_64_dialog_content = "Also, why do I feel like you're a little disrespectful to the City Lord?",
  ui_story_30460201_65_dialog_content = "Conflicts like this may add drama to the records.",
  ui_story_30460201_66_dialog_content = "But I've been wanting to ask you for a long time. The way you speak to the City Lord...",
  ui_story_30460201_67_option_content = "Don't you think there's a problem?",
  ui_story_30460201_68_dialog_content = "We're full of respect♪ for our dear City Lord♪",
  ui_story_30460201_69_dialog_content = "It's obvious that we treat him differently compared to you, PlayerName♪",
  ui_story_30460201_70_dialog_content = "Haha, compared to how they treat the other nobles, they're actually quite polite to you.",
  ui_story_30460201_71_dialog_content = "Hold on, wasn't I speaking for the City Lord just then?",
  ui_story_30460201_72_dialog_content = "Why do I feel like I'm the one under attack?",
  ui_story_30460201_73_dialog_content = "The City Lord obviously likes us and knows our personalities well.",
  ui_story_30460201_74_dialog_content = "I get it, so this is what it's like to be backed by someone in power...",
  ui_story_30460201_75_option_content = "Sir, will you mind?",
  ui_story_30460201_76_dialog_content = "It's just some wayward words of several children. I naturally won't take them seriously.",
  ui_story_30460201_77_dialog_content = "The City Lord selected us personally.",
  ui_story_30460201_78_dialog_content = "The City Lord knew the kind of kids we are and let us join the Choir.",
  ui_story_30460201_79_dialog_content = "Is this true?",
  ui_story_30460201_80_dialog_content = "Since I made this decision, it's obvious that their nature serves some purpose for me.",
  ui_story_30460201_81_dialog_content = "No wonder they're incorrigible! This must be what it's like to be backed by the powers-that-be...",
  ui_story_30460201_82_dialog_content = "Fine, since the City Lord doesn't mind, I'll continue to record your dramatic conflicts like this.",
  ui_story_30460201_83_dialog_content = "Let's continue recording. 3, 2, 1... Action—",
  ui_story_30460201_84_dialog_content = "Is this how you offer flowers? By sticking them behind people's ears?",
  ui_story_30460201_85_dialog_content = "Because it's pretty like that.",
  ui_story_30460201_86_dialog_content = "Because it's elegant like that.",
  ui_story_30460201_87_dialog_content = "A bunch of nonsense.",
  ui_story_30460201_88_dialog_content = "Well then, because it's true.",
  ui_story_30460201_89_dialog_content = "True? Then you better have enough evidence to support that.",
  ui_story_30460201_90_dialog_content = "The truth is, our dear sister Uriah also did something similar to us.",
  ui_story_30460201_91_dialog_content = "She would bless us with a smile and place a beautiful flower behind our ears.",
  ui_story_30460201_92_dialog_content = "That's what we learned. That's what we know.",
  ui_story_30460201_93_dialog_content = "Hmph, so you're intending to pin the responsibility onto someone else now?",
  ui_story_30460201_94_dialog_content = "Sorry, let me interrupt you again. Isn't there a little overlap with what you said earlier?",
  ui_story_30460201_95_dialog_content = "Dear PlayerName, you are always interrupting people.",
  ui_story_30460201_96_dialog_content = "The City Lord is extremely busy.",
  ui_story_30460201_97_dialog_content = "It was just supposed to be a few questions.",
  ui_story_30460201_98_dialog_content = "But now it has been extended indefinitely.",
  ui_story_30460201_99_dialog_content = "It has become a bigger problem♪",
  ui_story_30460201_100_dialog_content = "I don't mind, but you should indeed take note of this. My time is limited, so let's end this quickly.",
  ui_story_30460201_101_dialog_content = "Pardon me, I'll edit it after I record the things we say next. Please say something in conclusion.",
  ui_story_30460201_102_dialog_content = "3, 2, 1... Action—",
  ui_story_30460201_103_dialog_content = "We're not shirking our responsibilities—we're just stating the truth.",
  ui_story_30460201_104_dialog_content = "Furthermore, we're just kids. Why would you fuss over it?",
  ui_story_30460201_105_dialog_content = "You're children, but you must be taught a lesson when you need to be taught one.",
  ui_story_30460201_106_dialog_content = "Children shan't be spoiled.",
  ui_story_30460201_107_dialog_content = "As of now, the situation has become clear.",
  ui_story_30460201_108_dialog_content = "Although the Keating kids claimed they had never played pranks...",
  ui_story_30460201_109_dialog_content = "Lord Schwartz intends to hold them accountable after this.",
  ui_story_30460201_110_dialog_content = "This is the record report prepared by PlayerName, reporter of the Colossus.",
  ui_story_30460201_111_dialog_content = [[
Navigator: PlayerName
On-site reporter: PlayerName
Persons present: Niel, of the Keating Choir
          Kara, of the Keating Choir
          Pierre, of the Keating Choir
          Dian, of the Keating Choir
          Lord Schwartz, City Lord of Lumopolis]],
  ui_story_30460201_112_dialog_content = "How interesting. This report isn't bad at all.",
  ui_story_30460201_113_dialog_content = "Thank you for your support, City Lord. Your speech was simply perfect.",
  ui_story_30460201_114_dialog_content = "Although the incident is recorded differently from the ones in Lumopolis, you don't need to worry because I can understand it.",
  ui_story_30460201_115_dialog_content = "That's the end of this matter. I have other things to tend to now.",
  ui_story_30460201_116_dialog_content = "Take care, City Lord.",
  ui_story_30460201_117_dialog_content = "Dear PlayerName, you are ignoring us and only talking to the City Lord again.",
  ui_story_30460201_118_dialog_content = "PlayerName tries to be respectful,",
  ui_story_30460201_119_dialog_content = "but has a weird choice of words.",
  ui_story_30460201_120_dialog_content = "It was a failure.",
  ui_story_30460201_121_dialog_content = "You should be a bit more understanding since even the City Lord didn't say anything.",
  ui_story_30460201_122_dialog_content = "I haven't learned any court etiquette, so I'm already trying my best to be respectful.",
  ui_story_30460201_123_dialog_content = "The City Lord was also recorded as saying not to spoil you children.",
  ui_story_30460201_124_dialog_content = "But I feel like he's still quite tolerant of you.",
  ui_story_30460201_125_dialog_content = "Yes, indeed.",
  ui_story_30460601_1_dialog_content = "\"The moment you open this Tome of Black Magic,\"",
  ui_story_30460601_2_dialog_content = "\"You'll be transported to a mysterious, new world.\"",
  ui_story_30460601_3_dialog_content = "\"A world of wonder and magic,\"",
  ui_story_30460601_4_dialog_content = "\"Full of all kinds of extraordinary things.\"",
  ui_story_30460601_5_dialog_content = "\"A world for curious, lonely souls.\"",
  ui_story_30460601_6_dialog_content = "What do you think? This book's intro really knows how to grab the reader's attention, huh?",
  ui_story_30460601_7_dialog_content = "Is this \"Tome of Black Magic\" also the reason you guys are dressed up like this?",
  ui_story_30460601_8_dialog_content = "I can assure you, my ignorant, grown-up friend, that this book contains real and forbidden black magic.",
  ui_story_30460601_9_dialog_content = "And you say some stranger on the street gave this to you?",
  ui_story_30460601_10_dialog_content = "Are you sure the person wasn't lying?",
  ui_story_30460601_11_dialog_content = "Unlike you, we aren't so easily fooled.",
  ui_story_30460601_12_dialog_content = "The person kept going on and on about how terrifying the book was!",
  ui_story_30460601_13_dialog_content = "I'm sure that was just a stunt to get your attention.",
  ui_story_30460601_14_dialog_content = "Nevertheless, it was said that this book is only terrifying for adults. For little children like us, it's perfectly safe!",
  ui_story_30460601_15_dialog_content = "You're joking, right? That's just to trick you into buying this book!",
  ui_story_30460601_16_dialog_content = "How much is this book? Come on, I'll help you get your money back!",
  ui_story_30460601_17_dialog_content = "But it's for free.",
  ui_story_30460601_18_dialog_content = "Huh? So it was free...",
  ui_story_30460601_19_dialog_content = "Do you think there's still a problem now?",
  ui_story_30460601_20_option_content = "If it was free, I guess not.",
  ui_story_30460601_21_dialog_content = "♫Frugality is a lie adults use to hide, the horrible greed they keep inside!♪",
  ui_story_30460601_22_dialog_content = "I-I'm only keeping it out of curiosity!",
  ui_story_30460601_23_option_content = "Besides, nothing in life is free, you know!",
  ui_story_30460601_24_dialog_content = "Heh, at the very end of the day, money is still the issue.",
  ui_story_30460601_25_dialog_content = "Yeah, yeah, feel free to think whatever you want.",
  ui_story_30460601_26_dialog_content = "So what kind of book is this, anyway?",
  ui_story_30460601_27_dialog_content = "I suppose it wouldn't hurt to let you take a look.",
  ui_story_30460601_28_dialog_content = "If anything, you might be able to help.",
  ui_story_30460601_29_dialog_content = "It's an ancient book of forbidden magic. Most of it has already been lost.",
  ui_story_30460601_30_dialog_content = "But on the very last page...",
  ui_story_30460601_31_dialog_content = "\"Name: Titanic Monster...\"",
  ui_story_30460601_32_dialog_content = "(Huh, the rest is beyond recognition.)",
  ui_story_30460601_33_dialog_content = "Materials: bitter melon, celery, green pepper...",
  ui_story_30460601_34_dialog_content = "Wait, these are just common cooking ingredients!",
  ui_story_30460601_35_dialog_content = "You might want to take a look at the next line.",
  ui_story_30460601_36_dialog_content = "Coleoid tentacles, Koppia Caterpillar mucus, Mackerel fins.",
  ui_story_30460601_37_dialog_content = "Uhh... Just what in the heck are these things?",
  ui_story_30460601_38_dialog_content = "Some sticky, meaty ingredients of unknown origins, apparently.",
  ui_story_30460601_39_dialog_content = "Now do you believe this book is full of black magic?",
  ui_story_30460601_40_dialog_content = "(I'm pretty sure it's just a weird recipe, but it's probably scary for little kids like them. Maybe I should just play along for now...)",
  ui_story_30460601_41_dialog_content = "It's true, there's something scary about the materials listed here...",
  ui_story_30460601_42_dialog_content = "Just reading them out loud gives you the creeps.",
  ui_story_30460601_43_dialog_content = "Behold, this is the fabled Caelestite. How legendary you are!",
  ui_story_30460601_44_dialog_content = "I wouldn't joke around too much, guys. What if this spell can really summon a big, horrible monster?",
  ui_story_30460601_45_dialog_content = "That would be fantastic!",
  ui_story_30460601_46_dialog_content = "Let's split up and search for those ingredients!",
  ui_story_30460601_47_dialog_content = "Move out, everyone!",
  ui_story_30460601_48_dialog_content = "Hang on, you guys are serious about this?",
  ui_story_30460601_49_dialog_content = "But what if...",
  ui_story_30460601_50_dialog_content = "Cowards are doomed to hide behind the scenes.",
  ui_story_30460601_51_dialog_content = "Only the brave are blessed with miracles!",
  ui_story_30460601_52_dialog_content = "(That's easy enough for you to say, but I won't be able to just stand by if something really happens.)",
  ui_story_30460601_53_dialog_content = "If you want to prove yourself, you should provide us with a place to mix these ingredients.",
  ui_story_30460601_54_dialog_content = "Huh? Why me?",
  ui_story_30460601_55_dialog_content = "(Heh, I knew they needed me! Go ahead, tell me about how important I am!)",
  ui_story_30460601_56_dialog_content = "Because if you don't help, we'll have no choice but to use the potion on you.",
  ui_story_30460601_57_dialog_content = "Who knows, you might even wake up to a gigantic monster in your room!",
  ui_story_30460601_58_dialog_content = "So now you're threatening me?!",
  ui_story_30460601_59_dialog_content = "I believe grown-ups call this a \"quid pro quo\"?",
  ui_story_30460601_60_dialog_content = "Don't just throw words around when you don't actually know what they mean!",
  ui_story_30460601_61_dialog_content = "(I was planning on helping them from the start, but now it looks like I'm being forced to do it...)",
  ui_story_30460601_62_dialog_content = "There's a big pot in the kitchen. You can use that as your \"cauldron.\"",
  ui_story_30460601_63_dialog_content = "You severely overestimate the strength of your kitchenware.",
  ui_story_30460601_64_dialog_content = "Besides, we don't want to damage the Colossus in any way.",
  ui_story_30460601_65_dialog_content = "Are you guys absolutely sure you want to create a giant monster?",
  ui_story_30460601_66_dialog_content = "Of course we are! How could an eagle be soaring without his ambition roaring?",
  ui_story_30460601_67_dialog_content = "Fine, then I'll go ask Carleen if there are any abandoned laboratories in Lumopolis for you to use.",
  ui_story_30460601_68_dialog_content = "While we don't have much confidence in your ability to get things done...",
  ui_story_30460601_69_dialog_content = "With Lady Carleen on our side, we should have nothing to worry about!",
  ui_story_30460601_70_dialog_content = "Now let's get to work!",
  ui_story_30460601_71_dialog_content = "See you in a bit!",
  ui_story_30460601_72_dialog_content = "Did I hear you right, sweetie? You want bitter melon, celery, and green peppers?",
  ui_story_30460601_73_dialog_content = "I thought you always hated these things.",
  ui_story_30460601_74_dialog_content = "You're absolutely right, my dear mother.",
  ui_story_30460601_75_dialog_content = "And yet here you are asking for those healthy vegetables! Mama couldn't be more proud of you, Niel!",
  ui_story_30460601_76_dialog_content = "I'll let the kitchen staff pack you a big bag right now, okay?",
  ui_story_30460601_77_dialog_content = "Thank you, mama. Please don't add anything else, either.",
  ui_story_30460601_78_dialog_content = "My little Niel is finally learning to eat his vegetables! I'm so happy!",
  ui_story_30460601_79_dialog_content = "Is this enough?",
  ui_story_30460601_80_dialog_content = "Yes, mama. Now, I should get going before your tears start to flood the house.",
  ui_story_30460601_81_dialog_content = "Before you go, let me have the chef cook something for you. How does celery-stuffed bitter melon plus a plate of fried green peppers with parsley sound to you?",
  ui_story_30460601_82_dialog_content = "I want to watch you eat it all up!",
  ui_story_30460601_83_dialog_content = "I-I appreciate the concern, but I'm not really hungry right now, mama.",
  ui_story_30460601_84_dialog_content = "But it'll help you grow big and strong! Try a bite!",
  ui_story_30460601_85_dialog_content = "I'll just let you enjoy this delicious, nutritious meal, mama! I really, really have to be going now! Bye!",
  ui_story_30460601_86_dialog_content = "My, he ran off so quickly! My little Niel must be eating his veggies, after all!",
  ui_story_30460601_87_dialog_content = "Ok, that settles it! From now on, all the meals in this house must include these vegetables!",
  ui_story_30460601_88_dialog_content = "I've searched through every single book, but still nothing!",
  ui_story_30460601_89_dialog_content = "Kara? Are you looking for something in particular?",
  ui_story_30460601_90_dialog_content = "Yes, professor. I'm looking for a book on marine biology.",
  ui_story_30460601_91_dialog_content = "That's the very same subject I teach! Hahahaha! When did you become so interested in this field, Kara?",
  ui_story_30460601_92_dialog_content = "Well, I'm trying to learn more about a creature called a \"Coleoid.\" You must know all about it, since you've spent your whole life researching sea animals, right?",
  ui_story_30460601_93_dialog_content = "Indeed, nobody at the Academy has more knowledge on this subject than I do. In fact, I even keep some Coleoid tentacles in my office!",
  ui_story_30460601_94_dialog_content = "Older people sure love making up stories that never existed when they were younger, don't they?",
  ui_story_30460601_95_dialog_content = "I'm not making anything up, Kara! The tentacles are just in my closet! If I recall correctly, it was thirty years ago that...",
  ui_story_30460601_96_dialog_content = "If you're going to get lost in your memories, professor. Could you at least skip ahead to the important part?",
  ui_story_30460601_97_dialog_content = "Er, v-very well, then. In my youth, I stumbled upon a beautiful woman while researching different specimens near the ocean...",
  ui_story_30460601_98_dialog_content = "Let me guess: you fell in love, but she didn't feel the same?",
  ui_story_30460601_99_dialog_content = "Y-Yes, that's right. Anyway, I discovered a seaside karst cave shortly afterward, and in that cave...",
  ui_story_30460601_100_dialog_content = "The longer a story drags on, the worse the ending will be.",
  ui_story_30460601_101_dialog_content = "I happened upon these! See? Coleoid tentacles, just as I said!",
  ui_story_30460601_102_dialog_content = "And so, the brave hero finally lays claim to the treasure.",
  ui_story_30460601_103_dialog_content = "I couldn't agree more! After all, I was quite the courageous lad back in my day...",
  ui_story_30460601_104_dialog_content = "No, not you, professor. I'm the hero, and this is my reward for sitting through your long-winded story.",
  ui_story_30460601_105_dialog_content = "Eh? B-But I risked my life for these tentacles thirty years ago!",
  ui_story_30460601_106_dialog_content = "Which means you've had thirty years to celebrate your achievement, so what more could you want? Unless, of course, you made up the whole thing...",
  ui_story_30460601_107_dialog_content = "I can assure you, my story is entirely true. Go ahead and take them, but remember to...",
  ui_story_30460601_108_dialog_content = "Wait, where are you going? I wasn't finished speaking yet! Goodness, what on earth is that little girl up to?",
  ui_story_30460601_109_dialog_content = "Excuse me...",
  ui_story_30460601_110_dialog_content = "Well, if it isn't a little noble girl from Uptown!",
  ui_story_30460601_111_dialog_content = "There seems to be something wrong with your eyes.",
  ui_story_30460601_112_dialog_content = "We're just not used to seeing noble folks in our markets, is all.",
  ui_story_30460601_113_dialog_content = "Oh, miss, you are very pretty. Look at your shiny hair!",
  ui_story_30460601_114_dialog_content = "So what brings you to Lower Lumopolis, miss? You're not lost, are you?",
  ui_story_30460601_115_dialog_content = "If you would just let me speak, you wouldn't have to ask such unnecessary questions.",
  ui_story_30460601_116_dialog_content = "I need Mackerel fins, and I need them now. Please.",
  ui_story_30460601_117_dialog_content = "Even her voice is pretty, don't you think?",
  ui_story_30460601_118_dialog_content = "I remember now! She's part of the Keating Choir!",
  ui_story_30460601_119_dialog_content = "No wonder she has such a melodic voice!",
  ui_story_30460601_120_dialog_content = "Really? But I didn't hear what she said just now! Could you please say it again, miss?",
  ui_story_30460601_121_dialog_content = "To provoke the Choir is to incur the wrath of the God of Light.",
  ui_story_30460601_122_dialog_content = "O-Oh, I'm so sorry! I didn't mean to offend you!",
  ui_story_30460601_123_dialog_content = "Such a young age for a Choir member. That's really something for you!",
  ui_story_30460601_124_dialog_content = "Devote yourselves to the Light, not to your trivial mortal pursuits.",
  ui_story_30460601_125_dialog_content = "Sure, sure. Anyway, these Mackerel fins are pretty rare, but not as rare as having a noble for a customer. I'd be delighted to sell them to you!",
  ui_story_30460601_126_dialog_content = "The Koppia Caterpillar... Enormous in size yet gentle in temperament, it lives deep in the forests, particularly fond of sleeping.",
  ui_story_30460601_127_dialog_content = "As an offspring of a Knight, exploring the forest is just another necessary trial on my journey!",
  ui_story_30460601_128_dialog_content = "I may be alone, but I have nothing to fear as long as I have my sword!",
  ui_story_30460601_129_dialog_content = "The ground is soft, and there's an unusual scent in the air... Ah!",
  ui_story_30460601_130_dialog_content = "Gurgle, gurgle, gurgle—",
  ui_story_30460601_131_dialog_content = "(Where... Where am I? This warm, rhythmic breathing, and this sticky touch feeling...)",
  ui_story_30460601_132_dialog_content = "(I must be inside the mouth of a giant monster... Yet another trial to overcome!)",
  ui_story_30460601_133_dialog_content = "Whew... Finally free.",
  ui_story_30460601_134_dialog_content = "How disgusting... Just look at all this mucus. Thank goodness no one's around to see me like this.",
  ui_story_30460601_135_dialog_content = "You okay there, little one? What are you doing in the forest all by yourself?",
  ui_story_30460601_136_dialog_content = "I'm fine. My sword can pierce through any monster's throat!",
  ui_story_30460601_137_dialog_content = "Well, as far as I can tell, you had a run-in with a Koppia Caterpillar, didn't you?",
  ui_story_30460601_138_dialog_content = "They like to burrow into the ground and sleep with their mouths wide open. Did you happen to fall into its mouth?",
  ui_story_30460601_139_dialog_content = "Y-Yes, but only because the objective of my trial was to obtain some of its mucus! That's all!",
  ui_story_30460601_140_dialog_content = "Hey, watch your step! You don't want to fall into another one's mouth, do you?!",
  ui_story_30460601_141_dialog_content = "This must be the abandoned magic laboratory that Carleen told me about.",
  ui_story_30460601_142_dialog_content = "It's huge and far out of the way. Carleen even assigned a team of soldiers to guard the perimeter.",
  ui_story_30460601_143_dialog_content = "Even if something were actually to happen, I'm sure they could handle things quickly.",
  ui_story_30460601_144_dialog_content = "I guess Carleen must really care about letting those kids explore and learn.",
  ui_story_30460601_145_dialog_content = "I wonder what on earth they'll come up with?",
  ui_story_30460601_146_dialog_content = "♪The ingredients have been gathered, the time is now.♪",
  ui_story_30460601_147_dialog_content = "♪As the cauldron bubbles, read the incantation aloud!♪",
  ui_story_30460601_148_dialog_content = "♪Flickering flames and swirling concoction,♪",
  ui_story_30460601_149_dialog_content = "♪True magic requires no introduction!♪",
  ui_story_30460601_150_dialog_content = "♫May our young hearts breathe new life into this spell!♫",
  ui_story_30460601_151_dialog_content = "(Their eyes are shining so brightly. This must be what kids look like when they're having fun learning.)",
  ui_story_30460601_152_dialog_content = "Cough, cough! So much smoke!",
  ui_story_30460601_153_dialog_content = "No good! I can't see anything!",
  ui_story_30460601_154_dialog_content = "A shadow! Emerging from the smoke!",
  ui_story_30460601_155_dialog_content = "I think it's moving!",
  ui_story_30460601_156_dialog_content = "Oh no, I'm feeling a very strong wave of energy! Get behind me, guys!",
  ui_story_30460601_157_dialog_content = "And what exactly are YOU going to do?",
  ui_story_30460601_158_dialog_content = "Shouldn't you be the one hiding behind us?",
  ui_story_30460601_159_dialog_content = "We've told you before, we'll protect you when the need arises.",
  ui_story_30460601_160_dialog_content = "Please don't worry about us.",
  ui_story_30460601_161_dialog_content = "<color=#e8d9bb>Thump—</color>",
  ui_story_30460601_162_dialog_content = "What a deafening noise! Is it a mythical demon or something? No, it's an Eclipsite!",
  ui_story_30460601_163_dialog_content = "Please let us go.",
  ui_story_30460601_164_dialog_content = "Please open your eyes.",
  ui_story_30460601_165_dialog_content = "That's no monster at all—",
  ui_story_30460601_166_dialog_content = "It's just our professor.",
  ui_story_30460601_167_dialog_content = "What the devil is going on in here?",
  ui_story_30460601_168_dialog_content = "A forbidden spellbook of black magic?! I thought Kara was acting strange today, so I decided to follow her, but never did I expect...",
  ui_story_30460601_169_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_30460601_170_dialog_content = "It's finished!",
  ui_story_30460601_171_dialog_content = "A miracle is born!",
  ui_story_30460601_172_dialog_content = "It looks a little strange...",
  ui_story_30460601_173_dialog_content = "But also a little cute!",
  ui_story_30460601_174_dialog_content = "Is that... A giant cake?",
  ui_story_30460601_175_dialog_content = "Stay back! This cake is still the work of black magic! It's most likely poisonous!",
  ui_story_30460601_176_dialog_content = "Mmm, no wonder this cake is forbidden. It's delicious!",
  ui_story_30460601_177_dialog_content = "Y-You already took a bite?! Spit it out this instant, Kara!",
  ui_story_30460601_178_dialog_content = "They say tastiness is next to godliness, you know?",
  ui_story_30460601_179_dialog_content = "Not you too, Pierre?!",
  ui_story_30460601_180_dialog_content = "Wow, it really is delicious! Try some, professor!",
  ui_story_30460601_181_dialog_content = "I can see the children doing this, Mr. Caelestite, but you? Please, you must stop this foolishness...",
  ui_story_30460601_182_dialog_content = "I didn't know bitter melon and green peppers could be used to make something so delicious!",
  ui_story_30460601_183_dialog_content = "Bitter melon and peppers, you say? Well, it sounds healthy enough... Ah, to heck with it, I'll give it a try.",
  ui_story_30460601_184_dialog_content = "My word! It really is delicious!",
  ui_story_30460601_185_dialog_content = "And with that, our experiment is finally over.",
  ui_story_30460601_186_dialog_content = "I think not, Dian! This matter still needs to be reported to the Academy.",
  ui_story_30460601_187_dialog_content = "A cake this healthy and delicious should be shared with the entire school!",
  ui_story_30460601_188_dialog_content = "*Munch* This cake is great and all...",
  ui_story_30460601_189_dialog_content = "*Munch* But there's still one little problem.",
  ui_story_30460601_190_dialog_content = "*Munch* We were tricked, weren't we?",
  ui_story_30460601_191_dialog_content = "*Munch* This is clearly a recipe book, not a tome of black magic.",
  ui_story_30460601_192_dialog_content = "*Munch* You're just realizing this now...?",
  ui_story_30460601_193_dialog_content = "Wh... Why are you all lying on the floor like this? Are you hurt?",
  ui_story_30460601_194_dialog_content = "Oh, hey Chloe... No, no, don't cry! We're perfectly fine!",
  ui_story_30460601_195_dialog_content = "We just ate so much cake that we couldn't move.",
  ui_story_30460601_196_dialog_content = "And now Chloe the Crybaby got spooked.",
  ui_story_30460601_197_dialog_content = "Here, we saved one last piece of the cake.",
  ui_story_30460601_198_dialog_content = "Eat it. Hope it remedies your hurt feeling.",
  ui_story_30460601_199_dialog_content = "Did you make this cake yourselves?",
  ui_story_30460601_200_dialog_content = "Huh? How did you know?",
  ui_story_30460601_201_dialog_content = "Well, it looks a little too strange to be store-bought...",
  ui_story_30460601_202_dialog_content = "I guess you're right. I have no idea who would buy a cake like this...",
  ui_story_30460601_203_dialog_content = "It seems the crybaby has gotten more perceptive.",
  ui_story_30460601_204_dialog_content = "But still, her judgment is hardly objective.",
  ui_story_30460601_205_dialog_content = "Yes, our cake has an unsightly exterior,",
  ui_story_30460601_206_dialog_content = "But soon you will find that its taste is far superior!",
  ui_story_30460601_207_dialog_content = "Sorry, I know I shouldn't judge your cake by its appearance. I'll try it right now.",
  ui_story_30460601_208_dialog_content = "How is it?",
  ui_story_30460601_209_dialog_content = "It tastes great, but it's pretty high in calories. It's easy to gain weight if eating too much.",
  ui_story_30460601_210_dialog_content = "Calories? Gaining weight?",
  ui_story_30460601_211_dialog_content = "Wait, what did the lady who gave us this book say again?",
  ui_story_30460601_212_dialog_content = "\"This book is only terrifying for adults. For little children like us, it's perfectly safe!\"",
  ui_story_30460601_213_dialog_content = "So the \"terrifying\" part... Was the number of calories in the cake?!",
  ui_story_30460601_214_dialog_content = "...We've been duped..."
}
return config
